    vector<string> ansString = split(s, ",");
    int n =  ansString.size();
    vector<int> ans(n);
    for (int i = 0; i < n; i++) {
        ans[i] = stoi(ansString[i]);
    }
​
    vector<int> dp(MAX_COLS, 0);
    dp[0] = 1;

    for (int i = 0; i < n; i++){
        int num = ans[i];
        // 一维滚动数组，从后进行处理防止发生覆盖
        for (int j = captity; j >= num; j--) {
            dp[j] = dp[j] + dp[j-num];
        }
    }
    cout << dp[captity];
    return 0;
}

