function getResult(nums, capatity) {
  const n = nums.length;
​
  const dp = new Array(capatity + 1).fill(0);
  dp[0] = 1;
​
  for (let i = 1; i <= n; i++) {
    const num = nums[i - 1];
    for (let j = capatity; j >= num; j--) {
      dp[j] = dp[j] + dp[j - num];
    }
  }
​
  return dp[capatity];
