package main
​
import (
    "fmt"
    "strconv"
    "strings"
)
​
const MAX_COLS = 101
​
func main() {
    var s string
    var capacity int
    fmt.Scan(&s)
    fmt.Scan(&capacity)
​
    // 拆分字符串并转换为整数
    ansString := strings.Split(s, ",")
    n := len(ansString)
    ans := make([]int, n)
​
    for i := 0; i < n; i++ {
        num, _ := strconv.Atoi(ansString[i])
        ans[i] = num
    }
​
    // 定义 dp 数组
    dp := make([]int, MAX_COLS)
    dp[0] = 1
​
    // 处理 dp 转移
    for i := 0; i < n; i++ {
        num := ans[i]
        // 一维滚动数组，从后往前更新，防止覆盖
        for j := capacity; j >= num; j-- {
            dp[j] = dp[j] + dp[j-num]
        }
    }
​
    fmt.Println(dp[capacity])
}
